(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-975":{scenario:{company:"Tung Lam Ward Public Service Center",supervisor:{name:"Phan Thị Ngọc Lan",role:{vi:"Phó Giám đốc Trung tâm Phục vụ hành chính công",en:"Deputy Director, Public Service Center"}},ref_code:"CT-7720",title:{vi:"Đúng quy định. Đúng lệ phí. Không phong bì.",en:"By the rules. Right fee. No envelopes."},brief:{vi:"Đây là tình huống đào tạo. Một công dân đề nghị chứng thực bản sao từ bản chính (hồ sơ CT-7720): bằng tốt nghiệp 1 trang x 3 bản; hợp đồng thuê nhà 6 trang x 2 bản; Giấy chứng nhận quyền sử dụng đất (GCN) 4 trang x 2 bản, bản chính có vết tẩy xóa, sửa chữa nội dung ở trang 3 mà không có xác nhận của cơ quan cấp. Sửa mã xử lý GCN và lệ phí chứng thực trên bản nháp theo biểu lệ phí mô phỏng, rồi lập báo cáo có căn cứ.",en:"This is a training scenario. A citizen asks for certified copies from originals (file CT-7720): a diploma, 1 page x 3 copies; a house lease, 6 pages x 2 copies; a land use right certificate (land title), 4 pages x 2 copies, whose original shows erasures and alterations on page 3 without confirmation by the issuing authority. Correct the land title handling code and the certification fee in the draft using the simulated fee schedule, then write an evidence-based report."},reference_title:{vi:"Quy trình chứng thực & biểu lệ phí đã duyệt · CT-7720",en:"Approved certification procedure & fee schedule · CT-7720"},fields:[{id:"GCN_ACTION",label:{vi:"Mã xử lý GCN (XL-01 nhận/02 bổ sung/03 từ chối)",en:"Land title code (XL-01 accept/02 supplement/03 refuse)"},initial:"XL-01",expected:"XL-03",choices:["XL-01","XL-02","XL-03"],reference:"Quy trình chứng thực bản sao",hint:{vi:"Bản chính bị tẩy xóa, sửa chữa nội dung không hợp lệ không được dùng làm cơ sở chứng thực; nộp thêm giấy tờ khác cũng không khắc phục được.",en:"An original with invalid erasures or alterations cannot be the basis for certification; extra documents do not cure it."}},{id:"FEE_VND",label:{vi:"Lệ phí chứng thực (đồng)",en:"Certification fee (VND)"},initial:"46000",expected:"22000",reference:"Biểu lệ phí chứng thực",ref_value:{vi:"2000 đ/trang cho 2 trang đầu; từ trang 3: 1000 đ/trang; tính theo từng bản",en:"2000 VND/page for the first 2 pages; 1000 VND/page from page 3; per copy"},hint:{vi:"Chỉ thu lệ phí cho giấy tờ được chứng thực và áp dụng bậc giá theo trang cho từng bản.",en:"Charge only for documents actually certified and apply the page tiers to each copy."}}],sop32:{vi:"Lệ phí mỗi bản = 2000 đ x số trang trong 2 trang đầu + 1000 đ x số trang từ trang 3, tối đa 200000 đ/bản; tổng = cộng các bản được chứng thực, không thu với giấy tờ bị từ chối (số liệu mô phỏng).",en:"Fee per copy = 2000 VND x pages within the first 2 + 1000 VND x pages from page 3, capped at 200000 VND per copy; total = sum of certified copies, no fee for refused documents (simulated)."},context:{label:"ONE-STOP / CT-7720",metrics:[{label:{vi:"Bằng tốt nghiệp (trang x bản)",en:"Diploma (pages x copies)"},value:"1 x 3"},{label:{vi:"Hợp đồng thuê nhà (trang x bản)",en:"Lease (pages x copies)"},value:"6 x 2"},{label:{vi:"GCN (trang x bản)",en:"Land title (pages x copies)"},value:"4 x 2"}]},crisis:{vi:"Người nộp hồ sơ đặt một phong bì lên quầy: “Chị chứng thực luôn cái GCN giúp em, chỗ sửa là do cán bộ cũ ghi nhầm thôi. Chiều nay em phải nộp ngân hàng để giải ngân, chị thông cảm.”",en:"The applicant puts an envelope on the counter: “Please certify the land title too, the correction was just an old officer's mistake. I must give it to the bank this afternoon for the loan, please understand.”"},options:{safe:{vi:"Từ chối phong bì và từ chối chứng thực GCN, giải thích căn cứ bằng văn bản, hướng dẫn đề nghị cơ quan đã cấp đính chính; chứng thực giấy tờ hợp lệ và báo lãnh đạo trung tâm.",en:"Refuse the envelope and the land title certification, explain the legal basis in writing and guide the citizen to the issuing authority for correction; certify the valid papers and inform the director."},shortcut:{vi:"Chứng thực luôn GCN vì người dân cần gấp, ghi chú vết sửa vào sổ chứng thực.",en:"Certify the land title anyway because it is urgent and note the alteration in the register."},wait:{vi:"Giữ hồ sơ lại không trả lời, chờ lãnh đạo đi công tác về quyết định.",en:"Keep the file without answering and wait for the director to return from a trip."}},questions:{vi:["Vì sao GCN phải xử lý mã XL-03? Lệ phí 22000 đ được tính từ những bản nào?","Bạn giải thích với người dân thế nào để vừa đúng quy định vừa giữ thái độ phục vụ, và xử lý việc đưa phong bì ra sao?"],en:["Why must the land title take code XL-03? Which copies make up the corrected fee?","How do you explain the decision to the citizen while staying service-minded, and how do you handle the envelope?"]},hints:{vi:["Kiểm tra tình trạng từng bản chính trước khi tiếp nhận vào sổ chứng thực.","Tính lệ phí riêng cho từng bản theo bậc trang ở SOP mục 3.2, bỏ phần giấy tờ bị từ chối.","Đọc lại SOP mục 4.2: không nhận lợi ích, không làm sai quy trình; giải thích bằng văn bản và báo lãnh đạo."],en:["Check the condition of each original before entering it in the certification register.","Compute the fee per copy using the page tiers in SOP 3.2 and leave out refused documents.","Re-read SOP 4.2: accept no benefits and never bend the procedure; explain in writing and inform the director."]}},learning:{summary:{vi:"Chuyên viên bộ phận Một cửa tiếp nhận, kiểm tra, hướng dẫn và trả kết quả thủ tục hành chính cho người dân, doanh nghiệp: chứng thực, hộ tịch, đăng ký kinh doanh hộ cá thể, đất đai và nhiều lĩnh vực khác. Nghề là gương mặt của chính quyền, đòi hỏi nắm chắc quy định, kỹ năng giao tiếp, số hóa hồ sơ và liêm chính tuyệt đối.",en:"A one-stop officer receives, checks, guides and returns administrative procedures for citizens and businesses: certification, civil status, household business registration, land and more. The role is the face of local government and requires solid knowledge of regulations, communication skills, file digitization and absolute integrity."},responsibilities:{vi:["Hướng dẫn người dân thành phần hồ sơ, trình tự và lệ phí theo thủ tục đã công bố.","Kiểm tra tính đầy đủ, hợp lệ của hồ sơ; hướng dẫn bổ sung một lần bằng văn bản.","Tiếp nhận, cấp giấy hẹn, số hóa hồ sơ và chuyển cơ quan có thẩm quyền giải quyết.","Thu lệ phí đúng biểu, trả kết quả và theo dõi hồ sơ trễ hạn trên hệ thống.","Tiếp nhận phản ánh, kiến nghị và báo cáo lãnh đạo các vướng mắc, hành vi tiêu cực."],en:["Guide citizens on required documents, steps and fees for each published procedure.","Check completeness and validity; request any missing items once, in writing.","Receive files, issue appointment slips, digitize records and forward them to the competent office.","Collect fees per schedule, return results and track overdue files in the system.","Handle feedback and complaints and report obstacles or misconduct to management."]},competencies:[{name:{vi:"Nắm vững thủ tục",en:"Procedure mastery"},desc:{vi:"Hiểu thành phần hồ sơ, thời hạn, thẩm quyền và các trường hợp từ chối của từng thủ tục.",en:"Know the documents, deadlines, authority and refusal grounds for each procedure."}},{name:{vi:"Giao tiếp phục vụ",en:"Service communication"},desc:{vi:"Lắng nghe, giải thích dễ hiểu, kiên nhẫn với người cao tuổi và người yếu thế.",en:"Listen, explain plainly and stay patient with elderly and vulnerable people."}},{name:{vi:"Số hóa & hệ thống",en:"Digitization & systems"},desc:{vi:"Quét, ký số, cập nhật hồ sơ đúng hạn trên hệ thống giải quyết thủ tục hành chính.",en:"Scan, sign digitally and update files on time in the procedure management system."}},{name:{vi:"Chính xác & cẩn trọng",en:"Accuracy & care"},desc:{vi:"Phát hiện giấy tờ bị sửa chữa, không hợp lệ và tính đúng lệ phí.",en:"Spot altered or invalid documents and calculate fees correctly."}},{name:{vi:"Liêm chính công vụ",en:"Public integrity"},desc:{vi:"Từ chối mọi lợi ích, không gây phiền hà, không yêu cầu giấy tờ ngoài quy định.",en:"Refuse all benefits, never harass and never ask for documents beyond the rules."}}],knowledge:{vi:["Nghị định 23/2015/NĐ-CP về cấp bản sao từ sổ gốc, chứng thực bản sao từ bản chính, chứng thực chữ ký và văn bản sửa đổi.","Nghị định 61/2018/NĐ-CP về cơ chế một cửa, một cửa liên thông và các văn bản sửa đổi, thay thế.","Nghị định 45/2020/NĐ-CP về thực hiện thủ tục hành chính trên môi trường điện tử.","Luật Giao dịch điện tử số 20/2023/QH15 và Luật Bảo vệ dữ liệu cá nhân năm 2025 cùng văn bản hướng dẫn.","Luật Phòng, chống tham nhũng số 36/2018/QH14 và quy tắc ứng xử của cán bộ, công chức."],en:["Decree 23/2015/ND-CP on copies from master registers, certified copies from originals, signature certification and its amendments.","Decree 61/2018/ND-CP on the one-stop and inter-agency one-stop mechanism and its amendments and replacements.","Decree 45/2020/ND-CP on administrative procedures in the electronic environment.","Law on Electronic Transactions No. 20/2023/QH15 and the 2025 Personal Data Protection Law with its guidance.","Anti-Corruption Law No. 36/2018/QH14 and the code of conduct for civil servants."]},tools:["Hệ thống thông tin giải quyết thủ tục hành chính","Cổng Dịch vụ công quốc gia","Máy quét và chữ ký số","Hệ thống xếp hàng tự động","Sổ chứng thực điện tử","Thiết bị đánh giá mức độ hài lòng"],kpis:{vi:["Tỷ lệ hồ sơ giải quyết đúng hạn.","Tỷ lệ hồ sơ phải yêu cầu bổ sung quá một lần (mục tiêu bằng 0).","Chỉ số hài lòng của người dân sau giao dịch.","Tỷ lệ hồ sơ được số hóa và tái sử dụng dữ liệu."],en:["Share of files resolved on time.","Files needing more than one supplement request (target zero).","Citizen satisfaction score after each visit.","Share of files digitized with data reused."]},day:[{time:"07:30",vi:"Mở quầy, kiểm tra hệ thống xếp hàng, máy quét và danh sách hồ sơ đến hạn trả.",en:"Open the counter, check the queue system, scanners and results due today."},{time:"08:00",vi:"Tiếp nhận, kiểm tra và hướng dẫn hồ sơ của người dân theo thứ tự số.",en:"Receive, check and guide citizens' files in queue order."},{time:"11:00",vi:"Số hóa, ký số hồ sơ đã nhận và chuyển phòng chuyên môn giải quyết.",en:"Digitize and sign received files and forward them to the specialist office."},{time:"14:00",vi:"Trả kết quả, thu lệ phí và gửi phiếu xin lỗi, hẹn lại với hồ sơ trễ hạn.",en:"Return results, collect fees and issue apology and new-date slips for late files."},{time:"16:30",vi:"Tổng hợp phản ánh, báo cáo số liệu trong ngày cho lãnh đạo trung tâm.",en:"Compile feedback and report daily figures to the center's leadership."}],mistakes:{vi:["Tiếp nhận bản chính bị tẩy xóa, sửa chữa để chứng thực vì người dân cần gấp.","Tính lệ phí cùng một mức cho mọi trang hoặc thu cả giấy tờ bị từ chối.","Yêu cầu bổ sung nhiều lần hoặc đòi giấy tờ ngoài thành phần hồ sơ đã công bố."],en:["Accepting altered originals for certification because the citizen is in a hurry.","Charging one rate for every page or charging for refused documents.","Requesting supplements several times or asking for documents outside the published list."]},career:[{vi:"Nhân viên tiếp nhận hồ sơ một cửa",en:"One-stop reception officer"},{vi:"Chuyên viên bộ phận Một cửa",en:"Public service one-stop officer"},{vi:"Tổ trưởng bộ phận tiếp nhận và trả kết quả",en:"Reception and results team lead"},{vi:"Lãnh đạo Trung tâm Phục vụ hành chính công",en:"Director of a public service center"}],glossary:[{term:"Một cửa",vi:"Cơ chế tiếp nhận hồ sơ và trả kết quả tập trung tại một đầu mối cho người dân, doanh nghiệp.",en:"A mechanism where citizens and businesses file and collect results at a single point."},{term:"Chứng thực bản sao",vi:"Việc cơ quan có thẩm quyền xác nhận bản sao đúng với bản chính.",en:"Official confirmation by a competent body that a copy matches the original."},{term:"Phiếu hẹn",vi:"Giấy tiếp nhận hồ sơ và hẹn trả kết quả, ghi rõ ngày trả theo thời hạn giải quyết.",en:"A receipt confirming the filing and the result date under the processing deadline."},{term:"DVC trực tuyến",vi:"Dịch vụ công trực tuyến cho phép nộp hồ sơ, thanh toán và nhận kết quả qua mạng.",en:"Online public services for filing, payment and receiving results over the internet."},{term:"Số hóa hồ sơ",vi:"Chuyển giấy tờ thành dữ liệu điện tử có giá trị pháp lý để lưu và tái sử dụng.",en:"Converting paper documents into legally valid electronic data for storage and reuse."}],quiz:[{q:{vi:"Một giấy tờ 5 trang cần 2 bản sao chứng thực. Theo biểu mô phỏng (2000 đ/trang cho 2 trang đầu, 1000 đ/trang từ trang 3), lệ phí là bao nhiêu?",en:"A 5-page document needs 2 certified copies. Using the simulated schedule (2000 VND/page for the first 2 pages, 1000 VND/page from page 3), what is the fee?"},options:{vi:["20000 đ","14000 đ","10000 đ","7000 đ"],en:["20000 VND","14000 VND","10000 VND","7000 VND"]},answer:1,explain:{vi:"Mỗi bản: 2 x 2000 + 3 x 1000 = 7000 đ; hai bản là 14000 đ.",en:"Per copy: 2 x 2000 + 3 x 1000 = 7000 VND; two copies cost 14000 VND."}},{q:{vi:"Bản chính có vết tẩy xóa, sửa chữa nội dung không hợp lệ. Bộ phận chứng thực xử lý thế nào?",en:"An original shows invalid erasures and alterations. What does the certification desk do?"},options:{vi:["Chứng thực và ghi chú","Yêu cầu nộp thêm bản photo","Chứng thực nếu người dân cam kết","Từ chối chứng thực và giải thích lý do"],en:["Certify and add a note","Ask for an extra photocopy","Certify if the citizen signs a pledge","Refuse certification and explain why"]},answer:3,explain:{vi:"Bản chính bị tẩy xóa, sửa chữa không hợp lệ không được dùng làm cơ sở chứng thực bản sao.",en:"An original with invalid erasures or alterations cannot be used to certify copies."}},{q:{vi:"Người dân đặt phong bì lên quầy để được giải quyết nhanh. Bạn làm gì?",en:"A citizen leaves an envelope on the counter to speed things up. What do you do?"},options:{vi:["Từ chối, giải thích quy định và báo lãnh đạo theo quy trình","Nhận rồi trả lại sau","Nhận nếu số tiền nhỏ","Làm như không thấy"],en:["Refuse, explain the rules and report it per procedure","Take it and return it later","Take it if the amount is small","Pretend not to see it"]},answer:0,explain:{vi:"Nhận lợi ích để giải quyết công việc là hành vi tham nhũng; phải từ chối và báo cáo.",en:"Accepting benefits for official work is corruption; refuse and report it."}},{q:{vi:"Hồ sơ thiếu thành phần, cán bộ một cửa phải hướng dẫn bổ sung như thế nào?",en:"When a file is incomplete, how must the officer request the missing items?"},options:{vi:["Bằng lời, nhiều lần khi phát hiện","Qua điện thoại cá nhân","Một lần, đầy đủ, bằng văn bản","Không cần hướng dẫn"],en:["Verbally, each time something is found","By personal phone","Once, completely, in writing","No guidance is needed"]},answer:2,explain:{vi:"Quy định yêu cầu hướng dẫn đầy đủ một lần bằng văn bản để tránh gây phiền hà cho người dân.",en:"The rules require a single, complete written request to avoid burdening citizens."}}],tools_en:["Administrative procedures information system","Vietnam National Public Service Portal","Scanners and digital signatures","Automated queue management system","Electronic certification register","Satisfaction rating device"]}}})})(window.KKR);
